app.Use(async (context, next) =>
{
    var id = await AuthenticateAsync(context);   // this gate's own evidence
    if (!await Policy.AllowsAsync(id, context.Request))
    {
        context.Response.StatusCode = StatusCodes.Status403Forbidden;
        return;                                  // short-circuit: inner gate never runs
    }
    await next(context);                         // delegate to the inner gate
});
